// Decide which vulnerable packages can be fixed with a same-major yarn resolution.
const fs = require("fs");
const path = require("path");
const semver = require("semver");
const { execSync } = require("child_process");

const dir = path.join(__dirname, "..", "audit");
const lock = fs.readFileSync(path.join(dir, "yarn.lock"), "utf8");
const inst = {};
for (const b of lock.split("\n\n")) {
  const m = b.match(/^"?((?:@[^@\/]+\/)?[^@"]+)@/m);
  const v = b.match(/^  version "([^"]+)"/m);
  if (m && v) (inst[m[1]] = inst[m[1]] || new Set()).add(v[1]);
}

const adv = {};
for (const line of fs.readFileSync(path.join(dir, "audit.jsonl"), "utf8").trim().split("\n")) {
  const l = JSON.parse(line);
  if (l.type !== "auditAdvisory") continue;
  const a = l.data.advisory;
  if (!["critical", "high"].includes(a.severity)) continue;
  (adv[a.module_name] = adv[a.module_name] || new Map()).set(a.id, a);
}

const ok = {};
const skip = [];
for (const [name, m] of Object.entries(adv)) {
  const vers = [...(inst[name] || [])];
  const majors = new Set(vers.map((v) => semver.major(v)));
  if (majors.size !== 1) {
    skip.push(`${name}: several majors installed (${vers.join(", ")})`);
    continue;
  }
  const maj = [...majors][0];
  let all;
  try {
    all = JSON.parse(execSync(`npm view ${name} versions --json`, { stdio: ["ignore", "pipe", "ignore"] }));
  } catch (e) {
    skip.push(`${name}: npm view failed`);
    continue;
  }
  if (!Array.isArray(all)) all = [all];
  let pool = all.filter((v) => semver.valid(v) && semver.major(v) === maj && !semver.prerelease(v));
  // In 0.x, a minor bump can break the API, so stay on the installed minor.
  if (maj === 0) {
    const mins = new Set(vers.map((v) => semver.minor(v)));
    if (mins.size !== 1) {
      skip.push(`${name}: several 0.x minors installed (${vers.join(", ")})`);
      continue;
    }
    pool = pool.filter((v) => semver.minor(v) === [...mins][0]);
  }
  const best = semver.maxSatisfying(pool, "*");
  const still = [...m.values()].filter((a) => semver.satisfies(best, a.vulnerable_versions));
  if (still.length) {
    skip.push(`${name}: newest same-major ${best} still vulnerable; installed ${vers.join(", ")}`);
    continue;
  }
  if (vers.every((v) => semver.gte(v, best))) continue;
  ok[name] = { from: vers.join(", "), to: best };
}
console.log(JSON.stringify({ ok, skip }, null, 1));

